#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Velocity REST API client's functions list generator.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import json
import collections
import os


def add_optional(key, funcs):
    optional = "\nUse case with optional parameters::\n\n" \
        "\tvelocity_communicator.{0}({1})\n".format(
            key, ', '.join(
                ['{0}'.format(param)
                    for param in funcs[key]['required_parameters']] +
                ['{0}=<{0}>'.format(param)
                    for param in funcs[key]['optional_parameters']]
            )
        )
    return optional


def fill_template(key, funcs):
    header = \
        "\n{}\n".format(key.capitalize().replace('_', ' ')) + \
        "+" * len(key) + "\n"

    if len(funcs[key]['required_parameters']) > 0:
        req_params = ', '.join(funcs[key]['required_parameters'])
        t_req_params = "Required parameters: **{}**.\n\n".format(req_params)
    else:
        t_req_params = ''

    if len(funcs[key]['optional_parameters']) > 0:
        opt_params = ', '.join(funcs[key]['optional_parameters'])
        t_opt_params = "Optional parameters: *{}*.\n\n".format(opt_params)
    else:
        t_opt_params = ''

    if len(funcs[key]['optional_parameters']) > 0:
        t_opt_use_case = add_optional(key, funcs)
    else:
        t_opt_use_case = ''

    t_use_case = \
        "Use case::\n\n" \
        "\tvelocity_communicator.{0}({1})\n".format(
            key, ', '.join(funcs[key]['required_parameters'])
        )

    url = funcs[key]['url'].replace('\'', '')
    if 'format' in url:
        url = url.split('.')
        format_args = url[1][url[1].find("(") + 1:url[1].find(")")]
        format_args = format_args.replace(' ', '').split(',')
        format_args = ['<{}>'.format(x) for x in format_args]
        url = url[0].format(*format_args)
    t_url = \
        "\nUsed url: /velocity/{}\n".format(url)

    t_title = \
        "\nAPI title: {}\n".format(
            funcs[key]['api_title']
        )
    t_source = \
        "\nSource file: *services/{}*\n".format(
            os.path.split(funcs[key]['source'])[1]
        )

    template = header + t_req_params + t_opt_params + t_use_case + \
        t_opt_use_case + t_url + t_title + t_source
    return template


def prepare_func(func_file, service_name):
    func = {}
    func['required_parameters'] = func_file['required_parameters']
    func['optional_parameters'] = func_file['url_parameters']
    func['source'] = service_name
    func['url'] = func_file['url']
    if 'api_title' in func_file:
        func['api_title'] = func_file['api_title']
    else:
        func['api_title'] = ""
    return func


def make_document(funcs):
    body = ""
    header = \
        'Functions List\n**************\n'
    for key in funcs:
        body += fill_template(key, funcs)
    body = body[:-1]
    return header + body


def run():
    file_name = '../docs/source/functions/functions_list.rst'
    services_path = os.path.join(os.path.abspath(os.pardir), 'velocity_communicator\\services')
    services = []

    funcs = {}
    for file in os.listdir(services_path):
        if file.endswith(".json"):
            services.append(os.path.join(services_path, file))

    for service in services:
        with open(service, 'r') as file_fd:
            data = json.load(file_fd)
            for key in data.keys():
                funcs[key] = prepare_func(data[key], service)

    funcs = collections.OrderedDict(sorted(funcs.items()))
    document = make_document(funcs)

    with open(file_name, 'w+') as handler:
        handler.write(document)


if __name__ == "__main__":
    run()
